(()=>{'use strict';const q=s=>document.querySelector(s),A=[...document.querySelectorAll('.session[data-session]')],B=q('#progressBar'),S=q('#appStatus'),K='dnl-m1-done',say=x=>{if(S)S.textContent=x},load=()=>{try{return new Set(JSON.parse(localStorage.getItem(K)||'[]'))}catch(e){console.warn('[module1] storage',e);return new Set}},save=x=>{try{localStorage.setItem(K,JSON.stringify([...x]))}catch(e){console.warn('[module1] storage',e);say('La progression ne peut pas être enregistrée sur cet appareil.')}},D=load(),draw=()=>{A.forEach(x=>{let n=x.dataset.session,d=D.has(n),b=x.querySelector('.btn-complete');x.classList.toggle('session-completed',d);if(b){b.disabled=d;b.setAttribute('aria-pressed',d)}});let p=A.length?Math.round(100*D.size/A.length):0;if(B){B.style.width=p+'%';B.textContent=p+'%';B.setAttribute('aria-valuenow',p)}};document.addEventListener('click',e=>{let b=e.target.closest('.btn-complete');if(!b)return;D.add(b.dataset.session);save(D);draw();say(document.documentElement.lang==='es'?'Progreso guardado.':'Progression enregistrée.')});addEventListener('error',e=>console.warn('[module1] error',e.error||e.message));addEventListener('unhandledrejection',e=>console.warn('[module1] rejection',e.reason));draw();if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./module1-sw.js').catch(e=>console.warn('[module1] cache',e)),{once:true})})();
